cards.code:
@layer base, components;
@layer base { button { color: #143d2b; } }
@layer components { .save { color: #075985; } }

body { font-family: system-ui, sans-serif; line-height: 1.6; }
.article { max-inline-size: 65ch; }
.article h2 { font-weight: 700; text-wrap: balance; }

.bed-panel { container-type: inline-size; }
.bed-summary { display: grid; gap: 1rem; }
@container (min-width: 30rem) { .bed-summary { grid-template-columns: 1fr 1fr; } }

.save { transition: transform 150ms ease; }
.save:hover { transform: translateY(-2px); }
@media (prefers-reduced-motion: reduce) {
  .save { transition: none; }
  .save:hover { transform: none; }
}

@keyframes reveal { from { opacity: 0; } to { opacity: 1; } }
.notice { animation: reveal 200ms ease-out; }
@media (prefers-reduced-motion: reduce) { .notice { animation: none; } }

.btn.garden-action {
  --bs-btn-bg: #166534;
  --bs-btn-border-color: #166534;
  --bs-btn-hover-bg: #14532d;
  --bs-btn-hover-border-color: #14532d;
}

@import "tailwindcss";
@theme {
  --color-garden: #166534;
  --font-journal: Georgia, serif;
}
